select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_size in (46, 12, 29, 48, 31, 27, 2, 26) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Damages%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'MEDIUM POLISHED%' and p_size in (41, 29, 36, 21, 13, 30, 25, 49) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Issues%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'MEDIUM POLISHED%' and p_type not like 'LARGE POLISHED%' and p_size in (33, 8, 6, 40, 37, 35, 18, 34) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Problems%' or s_comment like '%Customer%Returns%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
select p_brand, p_type, p_size, count(distinct ps_suppkey) as supplier_cnt from partsupp, part where p_partkey = ps_partkey and p_brand <> 'Brand#52' and p_type not like 'LARGE POLISHED%' and p_type not like 'SMALL BURNISHED%' and p_type not like 'ECONOMY ANODIZED%' and p_size in (29, 10, 9, 41, 5, 7, 28, 27) and ps_suppkey not in ( select s_suppkey from supplier where (s_comment like '%Customer%Returns%' or s_comment like '%Customer%Complaints%') ) group by p_brand, p_type, p_size order by supplier_cnt desc, p_brand, p_type, p_size;
